package cn.guihualab.liveai;
import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34)
public class PlaybackControlTest {
 static class Output implements PlaybackControl.Output{float rate=1,volume=1;boolean unsupported,paused;int changes;public void speed(float rate){if(unsupported)throw new IllegalArgumentException("synthetic unsupported");this.rate=rate;changes++;}public float speed(){return rate;}public void volume(float value){volume=value;}public void pause(){paused=true;}}
 @Test public void unsupportedSpeedDoesNotThrowOrClaimTheRequestedRate() throws Exception {PlaybackControl c=new PlaybackControl();Output output=new Output();output.unsupported=true;c.request(1.8f,.3f);c.apply(output,true);JSONObject state=c.state();assertEquals("failed",state.getString("status"));assertEquals(1,state.getDouble("rate"),0);assertEquals(1.8,state.getDouble("requestedRate"),.0001);assertEquals(.3,output.volume,.0001);assertFalse(state.getString("error").isEmpty());c.request(1,.4f);c.apply(output,true);assertEquals("applied",c.state().getString("status"));assertEquals(0,output.changes);}
 @Test public void speedReadbackAndRouteResetAreReconciledAndFocusPauseIsPreserved() throws Exception {PlaybackControl c=new PlaybackControl();Output output=new Output();c.request(1.5f,.5f);c.apply(output,true);assertEquals(1.5,c.state().getDouble("rate"),0);output.rate=1;c.apply(output,false);assertEquals(1.5,output.rate,0);assertTrue(output.paused);assertEquals(2,output.changes);}
 @Test public void bufferCanSupportMaxSpeedStrictlyAboveTheDocumentedMinimum(){for(int minimum:new int[]{1024,9600,16384})assertTrue(PlaybackControl.bufferBytes(minimum)>minimum*2);try{PlaybackControl.bufferBytes(-2);fail();}catch(IllegalArgumentException expected){}}
 @Test public void startupMessagesNameTheirStageWithoutLeakingRawExceptions(){Exception raw=new IllegalArgumentException("Bearer synthetic-private-key");String focus=new AudioStartFailure("AUDIO_FOCUS",raw).userMessage(),output=new AudioStartFailure("AUDIO_OUTPUT_INIT",raw).userMessage();assertTrue(focus.contains("AUDIO_FOCUS"));assertFalse(focus.contains("权限"));assertFalse(focus.contains("synthetic-private"));assertTrue(output.contains("播放设备"));}
 @Test public void slowHardwareDoesNotBlockLatestRequestedValueAndCannotConfirmAStaleRequest()throws Exception{
  PlaybackControl c=new PlaybackControl();java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);Output output=new Output(){public void speed(float value){entered.countDown();try{release.await();}catch(InterruptedException e){throw new RuntimeException(e);}super.speed(value);}};c.request(2,1);Thread first=new Thread(()->c.apply(output,true));first.start();assertTrue(entered.await(2,java.util.concurrent.TimeUnit.SECONDS));java.util.concurrent.FutureTask<Void> latest=new java.util.concurrent.FutureTask<>(()->{c.request(1.25f,.4f);return null;});new Thread(latest).start();try{latest.get(500,java.util.concurrent.TimeUnit.MILLISECONDS);}finally{release.countDown();}first.join(2000);assertEquals("pending",c.state().getString("status"));assertEquals(1.25,c.state().getDouble("requestedRate"),0);c.apply(output,true);assertEquals("applied",c.state().getString("status"));assertEquals(1.25,c.state().getDouble("rate"),0);
 }
}
